post.description:
Create chatwidget customization for a specific hospital.

Expected JSON format:
{
    "chatwidget": {
        "theme": {
            "company_logo": "https://example.com/logo.png",
            "primary_color": "#FF0000",
            "secondary_color": "#00FF00",
            ...
        },
        "features": {
            "avarta_interaction_type": "voice",
            "face_analysis": true,
            "hair_analysis": false,
            ...
        },
        "avatar": {
            "avarta_language": "en"
        },
        "voice": {
            "voice_id": "voice_001"
        },
        "integration": {}
    }
}

